<script lang="ts">
 import {page} from '$app/state';
 import type {AccountPreferences,AccountProfilesGateway} from '../application/account-profiles';
 import type {ReaderPlatform,ReaderPreferences} from '$lib/features/reading/application/reader';
 import GoogleLink from '$lib/features/identity/presentation/GoogleLink.svelte';
 import type {GoogleLinkGateway} from '$lib/features/identity/application/google-link';
 import AvatarEditor from '$lib/features/identity/presentation/AvatarEditor.svelte';
 import type {AvatarGateway} from '$lib/features/identity/application/avatars';
 import {onMount,onDestroy,untrack} from 'svelte';
 import {goto,invalidateAll} from '$app/navigation';
 import type {AuthGateway,AuthResult} from '$lib/features/identity/application/auth';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {ThemeStore} from '../application/theme';
 import {initializeTheme,changeTheme,changeMotion} from '../application/theme';
 import type {Theme} from '../domain/theme';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {errorText} from '$lib/shared/presentation/messages';
 import Icon from '$lib/shared/presentation/ui/Icon.svelte';
 import type {IconName} from '$lib/shared/presentation/ui/types';
 const tabIcons:IconName[]=['sun','user','shield','bell','bookmark'];
 import Button from '$lib/shared/presentation/ui/Button.svelte';
 import ActionLink from '$lib/shared/presentation/ui/ActionLink.svelte';
 import StateMessage from '$lib/shared/presentation/ui/StateMessage.svelte';
 let {user,auth,preferences,avatars,googleLink,accountProfiles,reading}:{user:Account|null;auth:AuthGateway;preferences:ThemeStore;avatars?:AvatarGateway;googleLink?:GoogleLinkGateway;accountProfiles:AccountProfilesGateway;reading?:Pick<ReaderPlatform,'preferences'|'savePreferences'>}=$props();
 const {locale,change}=useLocale();
 const tabs=[['appearance','Көрініс','Вид'],['account','Аккаунт','Аккаунт'],['privacy','Құпиялық','Приватность'],['notifications','Хабарлар','Уведомления'],['reading','Оқу','Чтение']];
 let section=$derived(page.url.searchParams.get('section')||'appearance');
 let accountPrefs=$state<AccountPreferences|null>(null),prefsError=$state(''),prefsSaved=$state(false),prefsBusy=$state(false),readerPrefs=$state<ReaderPreferences|null>(null);
 let generation=0;
 let activeAccountId:string|undefined;
 function current(accountId:string,sequence:number){return sequence===generation&&user?.id===accountId;}
 async function loadPreferences(){if(!user)return;const accountId=user.id,sequence=generation;prefsError='';try{const loaded=await accountProfiles.preferences(accountId);if(current(accountId,sequence))accountPrefs=loaded;}catch{if(current(accountId,sequence))prefsError=text($locale,'Баптаулар жүктелмеді. Қайта көріңіз.','Не удалось загрузить настройки. Повторите.');}}
 async function savePreferences(){if(!user||!accountPrefs||prefsBusy)return;const accountId=user.id,sequence=generation,draft={...accountPrefs};prefsBusy=true;prefsSaved=false;prefsError='';try{const saved=await accountProfiles.save(accountId,draft);if(current(accountId,sequence)){accountPrefs=saved;prefsSaved=true;}}catch{if(current(accountId,sequence))prefsError=text($locale,'Сақталмады. Нұсқалар қайшылығында бетті қайта ашпас бұрын мәтініңізді көшіріп алыңыз.','Не сохранено. При конфликте версий скопируйте текст перед перезагрузкой страницы.');}finally{if(current(accountId,sequence))prefsBusy=false;}}
 function saveReader(){if(reading&&readerPrefs)reading.savePreferences(readerPrefs);}
 let motion=$state(false);
 let theme=$state<Theme>('system'),busy=$state(false),result=$state<AuthResult|null>(null);
 let displayName=$state(''),profileResult=$state<AuthResult|null>(null);
 onMount(()=>{theme=initializeTheme(preferences);motion=preferences.readMotion?.()||false;if(reading)readerPrefs=reading.preferences('manga');});
 $effect(()=>{const accountId=user?.id;untrack(()=>{if(accountId===activeAccountId)return;activeAccountId=accountId;generation++;accountPrefs=null;prefsError='';prefsSaved=false;prefsBusy=false;busy=false;result=null;profileResult=null;displayName=user?.displayName||'';if(accountId)void loadPreferences();});});
 onDestroy(()=>{generation++;});
 async function saveProfile(){if(!user||busy)return;const accountId=user.id,sequence=generation;busy=true;try{const saved=await auth.updateProfile(accountId,displayName);if(!current(accountId,sequence))return;profileResult=saved;if(saved.ok)await invalidateAll();}finally{if(current(accountId,sequence))busy=false;}}
 async function logout(){if(!user||busy)return;const accountId=user.id,sequence=generation;busy=true;try{const saved=await auth.logout();if(!current(accountId,sequence))return;result=saved;if(saved.ok){await invalidateAll();await goto('/');}}finally{if(current(accountId,sequence))busy=false;}}
 async function resend(){if(!user||busy)return;const accountId=user.id,sequence=generation,email=user.email;busy=true;try{const saved=await auth.resend(email);if(current(accountId,sequence))result=saved;}finally{if(current(accountId,sequence))busy=false;}}

</script>
<svelte:head><title>{text($locale,'Баптаулар','Настройки')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<div class="settings">
 <header class="settings-intro"><div><p class="eyebrow">{text($locale,'ӨЗІҢ ЫҢҒАЙЛА','ПОД СЕБЯ')}</p><h1>{text($locale,'Баптаулар','Настройки')}</h1><p class="intro-copy">{text($locale,'Аккаунт, оқу тәжірибесі және құпиялық.','Аккаунт, чтение и приватность.')}</p></div>{#if user}<a class="profile-link" href={'/users/'+encodeURIComponent(user.id)}><Icon name="user" size={16}/><span>{text($locale,'Профильді көру','Мой профиль')}</span></a>{/if}</header>
 <nav class="settings-tabs" aria-label={text($locale,'Баптау бөлімдері','Разделы настроек')}>{#each tabs as tab,i}<a href={'?section='+tab[0]} aria-current={section===tab[0]?'page':undefined}><Icon name={tabIcons[i]} size={16}/>{text($locale,tab[1],tab[2])}</a>{/each}</nav>
 {#if section==='appearance'}
 <section class="settings-panel"><h2>{text($locale,'Тақырып','Тема')}</h2><p class="hint">{text($locale,'Қараңғы, ашық немесе құрылғыңызға сай.','Тёмная, светлая или как на устройстве.')}</p>
 <div class="theme-choices" role="group" aria-label={text($locale,'Тақырып','Тема')}>{#each ['dark','light','system'] as choice}<button class="theme-choice" class:chosen={theme===choice} aria-pressed={theme===choice} onclick={()=>theme=changeTheme(preferences,choice)}><span class={'theme-preview '+choice} aria-hidden="true"><i></i><b></b></span><span>{choice==='dark'?text($locale,'Қараңғы','Тёмная'):choice==='light'?text($locale,'Жарық','Светлая'):text($locale,'Жүйе','Система')}</span></button>{/each}</div>
 <label class="field language" for="ui-language">{text($locale,'Сайт тілі','Язык сайта')}<select id="ui-language" value={$locale} onchange={event=>change(event.currentTarget.value==='ru'?'ru':'kk')}><option value="kk">Қазақша</option><option value="ru">Русский</option></select></label>
 {#if preferences.readMotion&&preferences.saveMotion&&preferences.applyMotion}<label class="toggle"><span>{text($locale,'Қозғалысты азайту','Уменьшить движение')}<small>{text($locale,'Анимацияларды барынша азайтады.','Сокращает анимации интерфейса.')}</small></span><input type="checkbox" role="switch" bind:checked={motion} onchange={event=>motion=changeMotion(preferences,event.currentTarget.checked)}/></label>{/if}</section>
 <p class="footnote">{text($locale,'Тақырып бірден қолданылады.','Тема применяется сразу.')}</p>
 {:else if section==='account'}
 {#if user}<section class="settings-panel account-panel">
 <form class="profile-form" onsubmit={event=>{event.preventDefault();void saveProfile();}}><label class="field" for="profile-name">{text($locale,'Көрсетілетін атыңыз','Публичное имя')}<input id="profile-name" bind:value={displayName} maxlength="40" autocomplete="nickname"/></label><Button type="submit" {busy} variant="ghost">{text($locale,'Атын сақтау','Сохранить имя')}</Button></form>
 {#if profileResult}<StateMessage kind={profileResult.ok?'success':'error'} title={profileResult.ok?text($locale,'Атыңыз сақталды','Имя сохранено'):errorText($locale,profileResult.code)}/>{/if}
 {#if accountPrefs}<fieldset disabled={prefsBusy}><label class="field bio-field" for="account-bio">{text($locale,'Қысқаша био','О себе')}<textarea id="account-bio" maxlength="500" rows="3" bind:value={accountPrefs.bio}></textarea></label></fieldset><Button busy={prefsBusy} variant="ghost" onclick={savePreferences}>{text($locale,'Бионы сақтау','Сохранить описание')}</Button>{#if prefsSaved}<StateMessage kind="success" title={text($locale,'Өзгерістер сақталды','Изменения сохранены')}/>{/if}{:else if !prefsError}<p class="hint">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}
 <div class="email-row"><div><h2>{text($locale,'Электрондық пошта','Электронная почта')}</h2><p class="hint account-email">{user.email}</p></div><span class="verification">{#if user.verified}<Icon name="check" size={14}/>{/if}{user.verified?text($locale,'Расталған','Подтверждена'):text($locale,'Расталмаған','Не подтверждена')}</span></div>
 {#if !user.verified}<Button {busy} onclick={resend}>{text($locale,'Растау хатын жіберу','Отправить подтверждение')}</Button>{/if}
 {#if googleLink}{#key user.id}<GoogleLink gateway={googleLink} accountId={user.id} verified={user.verified}/>{/key}{/if}
 {#if avatars}<details class="avatar-details"><summary>{text($locale,'Аватарды өзгерту','Изменить аватар')}</summary>{#key user.id}<AvatarEditor gateway={avatars} kind="user" actorId={user.id} ownerId={user.id} name={user.displayName||'Q'}/>{/key}</details>{/if}</section>
 <details class="more-actions"><summary>{text($locale,'Аккаунттың басқа әрекеттері','Другие действия аккаунта')}</summary><div class="settings-links"><ActionLink href="/reports">{text($locale,'Менің өтініштерім','Мои обращения')}</ActionLink><ActionLink href="/studio">{text($locale,'Аудармашы кабинеті','Кабинет переводчика')}</ActionLink>{#if user.role==='admin'}<ActionLink href="/admin">{text($locale,'Әкімші панелі','Администрирование')}</ActionLink>{/if}{#if user.role==='admin'||user.role==='moderator'}<ActionLink href="/moderation">Модерация</ActionLink>{/if}<Button onclick={logout} {busy} variant="ghost">{text($locale,'Шығу','Выйти')}</Button></div></details>
 {#if result}<StateMessage kind={result.ok?'success':'error'} title={result.ok?text($locale,'Дайын. Поштаңды тексер.','Готово. Проверь почту.'):errorText($locale,result.code)}/>{/if}
 {:else}<section class="settings-panel"><p class="hint">{text($locale,'Кітапхана мен оқу орнын басқа құрылғыларда да сақтау үшін кір.','Войдите, чтобы сохранять библиотеку и прогресс на других устройствах.')}</p><div class="settings-links"><ActionLink href="/login" variant="primary">{text($locale,'Кіру','Войти')}</ActionLink><ActionLink href="/register">{text($locale,'Тіркелу','Регистрация')}</ActionLink></div></section>{/if}
 {:else if section==='privacy'||section==='notifications'}
 {#if user}{#if accountPrefs}<section class="settings-panel"><fieldset disabled={prefsBusy}>
 {#if section==='privacy'}{#each [['public_profile','Жария профиль','Публичный профиль','Басқа оқырмандар профиліңізді көре алады.','Другие читатели могут видеть ваш профиль.'],['show_library','Оқу тізімдерін көрсету','Показывать библиотеку','Кітапханаңыздағы жария сөрелер профильде көрінеді.','Библиотека будет видна в профиле.'],['show_activity','Оқу белсенділігін көрсету','Показывать активность','Соңғы оқу әрекеттері профильде көрінеді.','Последние действия чтения видны в профиле.'],['allow_follow','Жазылуға рұқсат беру','Разрешить подписки','Оқырмандар жаңартуларыңызға жазыла алады.','Читатели могут подписаться на обновления.']] as item}<label class="toggle"><span>{text($locale,item[1],item[2])}<small>{text($locale,item[3],item[4])}</small></span><input role="switch" type="checkbox" bind:checked={accountPrefs[item[0] as 'public_profile'|'show_library'|'show_activity'|'allow_follow']}/></label>{/each}<p class="privacy-note">{text($locale,'Пошта, сақталған тараулар және жеке баптаулар жария профильде көрсетілмейді.','Почта, скачанные главы и личные настройки не отображаются в публичном профиле.')}</p>
 {:else}{#each [['notify_releases','Жаңа тараулар','Новые главы','Сөредегі тайтл жаңарғанда.','Когда обновляется тайтл в библиотеке.'],['notify_replies','Пікірге жауаптар','Ответы на комментарии','Пікіріңізге жауап келгенде.','Когда ответили на ваш комментарий.'],['notify_followers','Жаңа жазылушылар','Новые подписчики','Профиліңізге жазылған оқырмандар.','Когда на вас подписался читатель.'],['email_digest','Пошта хабарламалары','Почтовые уведомления','Апталық оқу жаңартулары.','Еженедельные обновления чтения.']] as item}<label class="toggle"><span>{text($locale,item[1],item[2])}<small>{text($locale,item[3],item[4])}</small></span><input role="switch" type="checkbox" bind:checked={accountPrefs[item[0] as 'notify_releases'|'notify_replies'|'notify_followers'|'email_digest']}/></label>{/each}{/if}</fieldset></section><div class="save-row"><Button busy={prefsBusy} onclick={savePreferences}>{text($locale,'Өзгерістерді сақтау','Сохранить изменения')}</Button></div>{#if prefsSaved}<StateMessage kind="success" title={text($locale,'Өзгерістер сақталды','Изменения сохранены')}/>{/if}
 {:else if !prefsError}<p class="hint">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}{:else}<ActionLink href="/login">{text($locale,'Баптаулар үшін кіріңіз','Войдите для настройки')}</ActionLink>{/if}
 {:else if section==='reading'}<section class="settings-panel">{#if readerPrefs}<label class="field">{text($locale,'Оқу режимі','Режим чтения')}<select bind:value={readerPrefs.mode} onchange={event=>{readerPrefs!.mode=event.currentTarget.value as 'pages'|'strip';saveReader();}}><option value="pages">{text($locale,'Бет бойынша','По страницам')}</option><option value="strip">{text($locale,'Тік айналдыру','Вертикальная лента')}</option></select></label><label class="field">{text($locale,'Оқу бағыты','Направление чтения')}<select bind:value={readerPrefs.direction} onchange={event=>{readerPrefs!.direction=event.currentTarget.value as 'auto'|'ltr'|'rtl';saveReader();}}><option value="auto">{text($locale,'Әдепкі','По умолчанию')}</option><option value="ltr">{text($locale,'Солдан оңға','Слева направо')}</option><option value="rtl">{text($locale,'Оңнан солға','Справа налево')}</option></select></label><label class="toggle"><span>{text($locale,'Оқу орнын сақтау','Сохранять прогресс')}<small>{text($locale,'Соңғы ашқан бетіңізден жалғастырасыз.','Продолжайте с последней открытой страницы.')}</small></span><input role="switch" type="checkbox" bind:checked={readerPrefs.saveProgress} onchange={event=>{readerPrefs!.saveProgress=event.currentTarget.checked;saveReader();}}/></label><label class="toggle"><span>{text($locale,'Келесі тарауды алдын ала жүктеу','Загружать следующую главу заранее')}<small>{text($locale,'Жылдам қосылымда, трафикті үнемдеу өшірулі болғанда.','При быстром соединении без экономии трафика.')}</small></span><input role="switch" type="checkbox" bind:checked={readerPrefs.prefetchNext} onchange={event=>{readerPrefs!.prefetchNext=event.currentTarget.checked;saveReader();}}/></label>{/if}</section><div class="settings-links"><ActionLink href="/saved">{text($locale,'Сақталған тараулар','Скачанные главы')}</ActionLink><ActionLink href="/library">{text($locale,'Кітапхана','Библиотека')}</ActionLink></div>{/if}
 {#if (section==='account'||section==='privacy'||section==='notifications')&&prefsError}<StateMessage kind="error" title={prefsError}/>{#if !accountPrefs}<Button onclick={loadPreferences}>{text($locale,'Қайта көру','Повторить')}</Button>{/if}{/if}
</div>
<style>
.settings{max-width:720px;margin:8px auto 36px}.settings-intro{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.12em;font-weight:700;color:var(--accent);margin-bottom:8px}.settings-intro h1{font-size:26px}.intro-copy{font-size:12px;color:var(--muted);margin-top:8px}.profile-link{display:flex;align-items:center;gap:6px;min-height:44px;border:1px solid var(--line);border-radius:8px;padding:6px 10px;font-size:11px;max-width:130px;flex-shrink:0}.settings-tabs{display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid var(--line);padding-bottom:22px;margin-bottom:22px}.settings-tabs a{display:flex;align-items:center;gap:6px;min-height:44px;padding:0 12px;border:1px solid var(--line);border-radius:7px;color:var(--muted);font-size:12px}.settings-tabs a[aria-current]{color:var(--accent);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 8%,transparent);outline:1px solid var(--accent);outline-offset:2px}.settings-panel{padding:20px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}h2{font-size:14px;margin:0 0 6px}.hint{font-size:12px;color:var(--muted)}.field{display:grid;gap:9px;margin:0 0 22px;font-size:13px;font-weight:600}.field input,.field select,.field textarea{font-weight:450;font-size:14px}.field textarea{resize:vertical}.theme-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0 24px}.theme-choice{min-height:110px;border:1px solid var(--line);background:transparent;color:var(--text);padding:10px;border-radius:8px;text-align:left;font-size:12px}.theme-choice.chosen{border-color:var(--accent);outline:1px solid var(--accent)}.theme-preview{height:55px;display:flex;flex-direction:column;justify-content:center;gap:8px;padding:10px;border-radius:4px;margin-bottom:8px;overflow:hidden}.theme-preview.dark{background:#18181b}.theme-preview.light{background:#fafafa}.theme-preview.system{background:linear-gradient(115deg,#18181b 50%,#fafafa 50%)}.theme-preview i{height:5px;width:40%;background:var(--accent);border-radius:1px}.theme-preview b{height:15px;background:#7775;border-radius:2px}.language{margin-bottom:12px}.toggle{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:78px;padding:16px 0;border-bottom:1px solid var(--line);cursor:pointer;font-size:14px;font-weight:600}.toggle:first-child{padding-top:0}.toggle:last-child{border-bottom:0;padding-bottom:0}.toggle span{min-width:0}.toggle small{display:block;font-size:12px;font-weight:400;color:var(--muted);margin-top:4px;line-height:1.4}.toggle input{appearance:none;position:relative;width:40px;min-width:40px;height:24px;min-height:24px;padding:0;border:0;border-radius:14px;background:var(--raised);flex-shrink:0;cursor:pointer}.toggle input:after{content:'';position:absolute;width:18px;height:18px;left:3px;top:3px;background:var(--muted);border-radius:50%}.toggle input:checked{background:var(--accent)}.toggle input:checked:after{left:19px;background:var(--accent-ink)}.toggle input:disabled{opacity:.5}.privacy-note{font-size:12px;background:color-mix(in srgb,var(--accent) 8%,transparent);border-left:2px solid var(--accent);padding:12px;margin-top:18px}.footnote{font-size:11px;color:var(--muted);margin-top:12px}.save-row{display:flex;justify-content:flex-end;margin:18px 0}.settings-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.profile-form{display:grid;gap:0}.profile-form .field{margin-bottom:10px}.profile-form :global(button){justify-self:start;margin-bottom:22px}.bio-field{margin-bottom:10px}.account-panel>:global(button){margin-bottom:20px}.email-row{display:flex;align-items:center;justify-content:space-between;gap:12px;border-block:1px solid var(--line);padding:20px 0;margin-top:22px}.account-email{overflow-wrap:anywhere}.verification{display:flex;align-items:center;gap:4px;font-size:10px;color:var(--muted);flex-shrink:0}.avatar-details{border-top:1px solid var(--line);margin-top:20px}summary{display:flex;align-items:center;min-height:44px;cursor:pointer;font-size:13px;color:var(--muted)}summary:before{content:'+';font-size:18px;margin-right:8px}details[open]>summary:before{content:'−'}.more-actions{margin-top:16px}fieldset{border:0;padding:0;margin:0;min-width:0}@media(max-width:400px){.settings-panel{padding:16px}.settings-intro{gap:8px}.profile-link{max-width:104px;font-size:10px;padding:6px}.settings-intro h1{font-size:24px}.theme-choice{padding:8px}.settings-tabs a{padding:0 9px}.email-row{align-items:start;flex-direction:column;gap:8px}}
</style>
